    exSaves: 'ይቆጥባል:',
    walletCaption: 'ጉግል ፣ አፕል ፣ ቴሌግራም ፣ ኢሜል ፣ ኤስኤምኤስ ወይም ማለፊያ ጋር ይመዝገቡ እና በጥቂት ጠቅታዎች ውስጥ የኪስ ቦርሳ ለእርስዎ ይፈጠራል ። ምንም የግል ቁልፍ አስተዳደር ወይም አያያዝ: ንብረቶችዎን ሙሉ በሙሉ እየተቆጣጠሩ ናቸው እና ገንዘብዎን በጭራሽ አንደርስም.',
    accountsDesc: 'ወደ DeHub በርካታ መንገዶች አሉ እና አንዳቸውም ቀድሞውኑ የኪስ ቦርሳ እንዲኖራቸው አይጠይቁም ። ከጉግል ፣ ከአፕል ወይም ከቴሌግራም ጋር ይግቡ ፣ ወደ ኢሜል አድራሻዎ ወይም በኤስኤምኤስ በተላከ ኮድ ፣ በስልክዎ ወይም በኮምፒተርዎ ላይ ማለፊያ ወይም ቀድሞውኑ የሚጠቀሙበትን የኪስ ቦርሳ በማገናኘት ። ከኪስ ቦርሳ መንገድ በስተቀር ሁሉም ነገር በጀርባው ውስጥ ለእርስዎ የማይመች የኪስ ቦርሳ ያመነጫል- ቁልፎቹን ይይዛሉ ፣ እኛ በጭራሽ አያያዝን አንወስድም ፣ እና ጋዝ ተወላጅ ምልክትን በጭራሽ ሳይገዙ መለጠፍ ፣ ጫፍ እና መሰብሰብ እንዲችሉ ስፖንሰር ይደረጋል ። እርስዎ ሲመዘገቡ ሳይሆን ያንን የኪስ ቦርሳ ለመጀመሪያ ጊዜ እንዲጠብቁት ብቻ ይጠየቃሉ ።',
    accountsB1Desc: 'ጉግል ፣ አፕል ወይም ቴሌግራም ፣ አንድ መታ ፣ ለእርስዎ የተፈጠረ የኪስ ቦርሳ እና ከመጀመሪያው ልጥፍ ስፖንሰር የተደረገ ጋዝ ።',
    accountsB3Desc: 'MetaMask, ቀስተ ደመና, እምነት, Phantom ወይም WalletConnect የሚናገር ማንኛውም ነገር ያገናኙ, እና አድራሻውን ለማረጋገጥ አንድ ጊዜ ይፈርሙ. የፊንቶም ምዝገባ እምቢ ካለ ምክንያቱም የኢቴሬም አድራሻው ታሪክ የለውም ፣ በምትኩ የሶላና የኪስ ቦርሳዎን ማረጋገጥ ይችላሉ ። የኪስ ቦርሳ ተጠቃሚዎች የራሳቸውን ጋዝ ይከፍላሉ ።',
    accountsB5Desc: 'በአዲሱ አባላት ማውጫ ውስጥ መሬቶችን የሚቀላቀሉ እና ለመጀመሪያዎቹ ሰላሳ ቀናት ከስማቸው አጠገብ አዲስ አባል ቺፕ የሚሸከሙ ሁሉ ማህበረሰቡ እነሱን ማየት እና መቀበል ይችላል ። አዳዲስ አባላትም አማራጭ የሚመራ የእግር ጉዞ ይሰጣሉ ፣ ይህም በኋላ ከቅንብሮች እንደገና ሊከፈት ይችላል ።',
    accountsB6Desc: 'ይምረጡ "በጣት አሻራ ይቀጥሉ" እና ማለፊያ ራሱ መለያ ነው — ኢሜይል የለም ፣ የስልክ ቁጥር የለም ፣ የይለፍ ቃል የለም ። ተመሳሳይ ማለፊያ በድር ጣቢያው እና በ Android መተግበሪያ ውስጥ ይሠራል ።',
    accountsB7: 'አስመጣ ወይም ስደተኛ:',
    accountsB7Desc: 'የምዝገባ ወረቀቱ ቀድሞውኑ የያዙትን የኪስ ቁልፎች ለማስመጣት እና የቀድሞውን የ DeHub መለያ ለመሰደድ የተለየ አማራጮች አሉት ፣ ስለሆነም አዲስ የምዝገባ ወረቀቶች በመካከላቸው መምረጥ በጭራሽ አያስፈልጋቸውም ።',
    accountsB8: 'በመተው ላይ:',
    accountsB8Desc: 'መለያዎን ከቅንብሮች እራስዎ መሰረዝ ይችላሉ ። የመጠባበቂያ ቅጂዎችን ጨምሮ የእርስዎ መገለጫ ፣ ሰቀላዎች እና የተከማቹ ሚዲያዎች ተሰርዘዋል ፣ እና ከአፕል አገናኝ ጋር መግባት ተሰርዟል ። ለሕዝብ ብሎክቼይን ቀድሞውኑ የተፃፈ ማንኛውም ነገር እዚያ ይቆያል ።',
    uploadGallery: 'አንድ ልጥፍ ከአንድ ይልቅ በርካታ ምስሎችን ሊሸከም ይችላል-በአራት ያለ ባጅ ፣ በእያንዳንዱ ባጅ ደረጃ ወደ ሃያ በመጨመር ፣ እና እያንዳንዱ ምስል እስከ 42.069 ሜባ ሊደርስ ይችላል ። ከመለጠፍዎ በፊት ምስሎቹን ወደሚፈልጉት ቅደም ተከተል ይጎትቱ ፣ ይጎትቱ ወይም ይፃፉባቸው ፣ እና የመጀመሪያውን ፋይል በሙሉ ጥራት ፣ በፒንች እና በዞም ለማየት ማንኛውንም የፎቶ ሙሉ ማያ ገጽ ይክፈቱ ።',
    labelComposerTools: 'ኮምፖዚተር መሣሪያዎች:',
    uploadComposerTools: 'በቀጥታ ወደ ዘፋኙ ውስጥ ምስሎችን ወይም ቪዲዮዎችን ይለጥፉ ፣ መላውን ልጥፍ እንደ ረቂቅ ያስቀምጡ ፣ በኋላ ላይ (በመገለጫዎ ላይ የታቀዱ ልጥፎች ያሳዩ) ፣ ምልክት ያድርጉት "ለልጆች የተሰራ" ወይም ብስለት ፣ እና በተመሳሳይ እርምጃ ወደ ሌሎች ማህበራዊ መለያዎችዎ ይላኩ ። የቪዲዮ ሽፋን በኋላ ከአርትዕ ልጥፍ ሊለወጥ ይችላል ።',
    profileB1: 'ዥረት ደረጃ:',
