    dpayDesc: 'DeHub ክፍያ: Stripe በኩል ካርድ ጋር ይግዙ, ወይም ከሌሎች ሰንሰለቶች ከ crypto ጋር, ከ $ 0.50',
    topUpCardDesc: 'የግዢው ገጽ በ DeHub Pay ላይ ይሠራል ። በካርድ ይክፈሉ ፣ ወይም በሌላ ሰንሰለት ላይ በሚይዙት ምስጢራዊ ክሪፕቶ ይክፈሉ እና ለእርስዎ ይቀየራል ። ዝቅተኛው $ 0.50 ነው. ETH እና USDC እንዲሁ በ MoonPay በኩል በካርድ ሊገዙ ይችላሉ ፣ ቀድሞውኑ ባለው ሰንሰለት ላይ ፣ እና መተግበሪያው በፈረመዎት የኪስ ቦርሳ ውስጥ በቀጥታ ይወርዳሉ ። አንዴ የግዢ መሬቶች በአንድ መታ ውስጥ ለምግብ ማጋራት ይችላሉ ።',
    badgeUnlock4: 'ልዕለ ኃያላን ፣ የመገለጫ መዋቢያዎች ፣ ተጨማሪ የመገለጫ ቦታዎች ፣ በእያንዳንዱ ልጥፍ ተጨማሪ ምስሎች ፣ እና የራስዎ ኢሞጂ ፣ ተለጣፊ እና ጂአይኤፍ ጥቅሎች ።',
    tipDesc3: 'ጠቃሚ ምክሮች ልጥፎች, አስተያየቶች, ቀጥተኛ መልዕክቶች እና የቀጥታ ዥረቶች ላይ ይሰራሉ. የ DeHub ምልክቶች አጭር ከሆኑ, ጫፍ ወረቀት ሌሎች ሚዛኖችዎን ያቀርባል — USDC, ETH ወይም በመሠረቱ ላይ ምልክቶች, BNB ሰንሰለት, Robinhood ሰንሰለት ወይም አርክ — እና ጫፍ ከመውጣቱ በፊት ለእርስዎ ይቀይራቸዋል. አንድ ልጥፍ ከጣሱ በኋላ የእሱ ጠቃሚ አዝራር ቀደም ሲል የሰጡትን የት ማየት እንዲችሉ የሚያብረቀርቅ አልማዝ ያሳያል ።',
    liveStreamDesc: 'በቀጥታ ከፖስታው አቀናባሪ ፣ በአሳሽዎ ውስጥ ወይም ከኮዶደር ይሂዱ ። ዥረቶች ለ DeHub\'s Ingest ያትማሉ እና በእውነተኛ ጊዜ በ WebRTC ላይ ይጫወታሉ ፣ አንድ አውታረ መረብ ወደ ትልቁ መድረስ በማይችልበት ጊዜ Livepeer እንደ አውቶማቲክ ውድቀት ። እያንዳንዱ ዥረት ያለፍቃድ እና ሳንሱር ተከላካይ ነው ፣ የራሱ ውይይት አለው ፣ እና እሱ ሲያበቃ ወደ እንደገና ይለውጣል ።',
    keyFeat1: 'የቀጥታ ስርጭት, ላይ-ቻይን Minting አማራጭ ጋር ይሂዱ',
    keyFeat2: 'ጠቃሚ የስጦታ እነማዎች, እና ጠቃሚ መልዕክቶች ዥረት ላይ ጮክ ማንበብ',
    keyFeat5: 'ለእያንዳንዱ ዥረት ውይይት ፣ ማን እንደሚቀላቀል እና እያንዳንዱን ስጦታ ያሳያል',
