    supportedTokensDesc: 'ጠቃሚ ምክሮች, ስጦታዎች እና መክፈቻዎች በ DeHub ምልክቶች ውስጥ ይቀመጣሉ, ነገር ግን ከሌሎች ሚዛኖች መክፈል ይችላሉ — USDC, ETH ወይም በመሠረቱ ላይ ምልክቶች, BnB ሰንሰለት, Robinhood ሰንሰለት ወይም Arc — እና እነሱ ለእርስዎ ተለውጠዋል.',
