    webStreamingDesc: 'ካሜራዎን ወይም ማያ ገጽዎን በማጋራት ከአሳሽዎ በቀጥታ ይሂዱ ፣ ካሜራው እርስዎ በሚያሰራጩበት ጊዜ ተግባራዊ ይመስላል',
    externalStreamingDesc: 'በቅንብሮች እና በ Go Live ወረቀት ላይ ከሚታየው ቋሚ ዥረት ቁልፍ እና አገልጋይ ጋር OBS ፣ Streamlabs ወይም ማንኛውንም የ RTMP ኢንኮደር ይጠቀሙ',
