    subsDesc: 'ፈጣሪዎች የደንበኝነት ምዝገባዎችን በቀጥታ ከመገለጫቸው ይሸጣሉ ። እቅዶች በአሜሪካ ዶላር ዋጋ የሚከፈሉ ሲሆን በዴሆብ ማስመሰያዎች በቀጥታ ዋጋ ይከፈላሉ ፣ እና የፈጣሪ ድርሻ በቀጥታ በኪስ ቦርሳቸው ውስጥ ፣ ያነሰ የዴሆብ ባጅ-ደረጃ ክፍያ ። የደንበኝነት ምዝገባ ብቻ ልጥፎች እውነተኛ በር ናቸው - ያልተመዘገቡ ሰዎች ልጥፉን ሳይሆን አንድ መስመር ሻይ ያያሉ ።',
