    forSubs4: 'በዶላር የማይንቀሳቀስ ዋጋ',
    messagesDesc: 'በ DeHub ላይ ቀጥተኛ መልዕክቶች በነባሪ የተመሰጠሩ ፣ ቁጥጥር ሊደረግባቸው እና ከዘመናዊ መልእክተኛ ከሚጠብቋቸው መቆጣጠሪያዎች ጋር መምጣት ይችላሉ ። ጽሑፍ ከመላኩ በፊት በመሣሪያዎ ላይ የታተመ ነው ፣ ፈጣሪዎች ሰዎችን ለመላክ ሊያስከፍሉ ይችላሉ ፣ እና ውይይቶች በሚወያዩበት ጊዜ አሰሳውን መቀጠል እንዲችሉ በማያ ገጹ ጥግ ላይ ።',
    msg4: 'ፎቶዎች, ቪዲዮ, ጂአይኤፍ እና የተለጠፉ ምስሎች',
