    msg10: 'ሙሉ ማያ ጥሪዎች ፣ እና ከድር የተቀመጠው ጥሪ የሌላውን ሰው ስልክ ይጣራል',
    msg11: 'ኦፕቲንግ ኦንላይን ሁኔታ: አረንጓዴ ነጥብ የሚታይው ለማጋራት ከመረጡ ብቻ ነው',
    priv4: 'ማን ሊልክዎት እንደሚችል ይምረጡ-ሁሉም ሰው ፣ እርስዎ የሚከተሏቸው ሰዎች ፣ ማንም አዲስ ወይም ማንም',
    mon1: 'አንድ ሰው እርስዎን ከመላክዎ በፊት በ DeHub ምልክቶች ውስጥ አነስተኛ ጠቃሚ ምክር ይጠይቁ',
    mon2: 'ክፍያ በመላክ አዝራር ላይ ይታያል, ከመጀመሪያው የተከፈለ መልእክትዎ በፊት ማስጠንቀቂያ ጋር',
    mon3: 'የፈጣሪ ዲኤም እቅዶች የትኞቹ የመልዕክት አይነቶች እንደተፈቀዱ መገደብ እና አነስተኛ ጠቃሚ ምክር ማዘጋጀት ይችላሉ',
    mon4: 'የውይይት ውስጥ ጠቃሚ ምክር ፣ ከማንኛውም ምልክቶች ይከፍላሉ',
    militaryGrade: 'ኢንክሪፕት ጽሑፍ',
    militaryGradeDesc: 'የመልእክት ጽሑፍ እና ካፕቶች በመሣሪያዎ ላይ የተመሰጠሩ ናቸው ቁልፎች እርስዎ እና ሌላኛው ሰው ብቻ ይይዛሉ ። ሌላኛው ሰው ኢንክሪፕት የተደረገባቸው መልዕክቶችን በጭራሽ ካልከፈተ መልዕክቱ በምትኩ ያልተስተካከለ ይላካል ።',
    privateByDesignDesc: 'DeHub የተመሰጠረ መልዕክቶች ብቻ ciphertext ያከማቻል. ቁልፎችዎ በመሣሪያዎ ላይ ከአንድ የኪስ ቦርሳ ፊርማ የተገኙ ናቸው እና በጭራሽ ወደ እኛ አይላኩም ።',
    secureMediaSharing: 'ኢንክሪፕት ያልተደረገበት',
    secureMediaDesc: 'ፎቶዎች, ቪዲዮ እና ፋይሎች ገና መጨረሻ-ወደ-መጨረሻ የተመሰጠረ አይደለም, እና DeHub እርስዎ መልዕክት ማን እና መቼ ማየት ይችላሉ, እያንዳንዱ መልእክተኛ መልዕክቶችን ማድረስ አለበት እንደ.',
