    affiliateB1Desc: 'እያንዳንዱ መለያ አጫጭር /አር/ አገናኞችን ጨምሮ በየትኛውም ቦታ ሊያጋሩት የሚችሉት ልዩ የማጣቀሻ አገናኝ እና ኮድ አለው ። የማጣቀሻ አገናኝ በ DeHub ላይ በማንኛውም ገጽ ላይ ሊያመለክት ይችላል ፣ የግብዣ ገጽ በርካታ መዳረሻዎችን ሊያቀርብ ይችላል ፣ እና የሚያጋሯቸው የብሎግ መጣጥፎች አገናኝዎን በራስ-ሰር መሸከም ይችላሉ ።',
    affiliateB3Desc: 'ተባባሪ ዳሽቦርድ ጠቅታዎችዎን ፣ ፊርማዎችዎን እና ገቢዎን ያሳያል ፣ እና የግብዣ ገጽዎን እና የአጋሮቹን ምስል እንዲያበጁ ያስችልዎታል ። የእራስዎ ጉብኝቶች አይቆጠሩም ።',
    aiSuiteB3Desc: 'በመልዕክቶችዎ ውስጥ ለ @ረዳት በቀላል ቋንቋ መተግበሪያን ይግለጹ እና ይገነባል ፣ ከዚያ ሊጋራ የሚችል የቀጥታ ቅድመ-እይታ አገናኝ ይሰጥዎታል dehub.io/builder ውይይቱን ለእርስዎ ይጀምራል ።',
    aiSuiteCreditsDesc: 'ትውልዱ በዴሆብ ቶከንስ ውስጥ ይከፈላል ። አገልጋዩ ከመሮጡ በፊት የአንድን ሥራ ዋጋ ይጠቅሳል ፣ አንድ ዝውውር ያፀድቃል ፣ እና ክፍያ በሰንሰለት ላይ ከተረጋገጠ በኋላ ሥራው ይጀምራል ። እያንዳንዱ የኪስ ቦርሳ እሱን ለመሞከር በዝቅተኛ ዋጋ ሞዴሎች ላይ አምስት ነፃ ምስሎችን ያገኛል ፣ እና በፈጣሪ ገጽዎ ላይ የዶላር ዋጋ ያላቸው ምልክቶች ሚዛን በእያንዳንዱ ጊዜ ያለ የኪስ ፊርማ ለስራዎች ሊከፍሉ ይችላሉ ። የደረጃ አጠራር በተመሳሳይ መንገድ ይከፈላል ፣ በደቂቃ ።',
    adsPortalDesc: 'ንግዶች በራስ-ሰር የማስታወቂያ ፖርታል በኩል በ DeHub ላይ ዘመቻዎችን ማካሄድ ይችላሉ — ዘመቻዎችን ይፍጠሩ ፣ ከ DeHub ምልክቶች ጋር አናት ላይ እና አፈፃፀምን ይከታተሉ ፣ ማስታወቂያዎች በአገር ውስጥ ወደ ምግብ ውስጥ ያገለግላሉ ። በአንድ ልጥፍ ገጽ ላይ አስተያየቶቹ ከማንኛውም ማስታወቂያ በፊት ይመጣሉ ፣ እና አንባቢዎች አነስተኛ ማስታወቂያዎችን ለማየት መጠየቅ ይችላሉ ።',
    notificationsB1Desc: 'በቅንብሮች ውስጥ የግማሽ ምድብ ምርጫዎች በጭራሽ ምን እንደሚላክ ይወስናሉ ፣ ስለሆነም ምክሮችን መያዝ እና ምላሾችን መጣል ይችላሉ ። ትሮች በእንቅስቃሴ ደረጃ የተሰጣቸው ናቸው ፣ እያንዳንዳቸው የራሳቸውን ያልተነበቡ ቆጠራ ያሳያሉ ፣ እና በሰዓት ምን ያህል እንደሚደርሱ ገደብ ጋር ለህዝብ የውይይት ማንቂያዎች መምረጥ ይችላሉ ።',
    notificationsB6: 'ባጆች:',
