    kidsDesc: 'የልጆች ሁነታ ለልጆች አንድ ቦታ ወደ መሣሪያ ይቀይራል. በእሱ ላይ ፣ DeHub የሚያሳየው በልጆች ላይ የታተሙ ፈጣሪያቸውን ብቻ ይለጥፋል ፣ በመተግበሪያው ውስጥ በሁሉም ቦታ ፣ እና ጨካኝ ወይም ብጁ ኢሞጂዎች ይጠበቃሉ ። በ DeHub ላይ ሌላ ምንም ነገር እሱን በመጠቀም አንድ ልጅ ይደርሳል.',
    kidsB1: 'በፒን የተጠበቁ:',
    kidsB1Desc: 'በቅንብሮች ውስጥ ያብሩ እና ከ 4 እስከ 8 አሃዞች ፒን ይምረጡ ። እንደገና ለማጥፋት ተመሳሳይ ፒን ያስፈልጋል ፣ እና የተሳሳተ ፒን መሣሪያውን መክፈት አይችልም ።',
    kidsB2: 'ለልጆች የተሰራ:',
    kidsB2Desc: 'በፈጣሪው ውስጥ "ለልጆች የተሰራ" የሚል ልጥፍ ምልክት ያድርጉ እና ያረጋግጣሉ ። ልጥፉ ከዚያ በልጆች ሁነታ ውስጥ ይታያል ፣ ከተለመደው ምግቦች ይወጣል ፣ በፈጣሪ መገለጫ እና በፍለጋ ላይ ይቆያል ፣ እና በእሱ ላይ አስተያየት መስጠት የሚችሉት የልጆች ሁነታ ብቻ ነው ። አንድ ልጥፍ ሁለቱም ብስለት እና ለልጆች የተሰራ ሊሆን አይችልም.',
    tocPacks: 'Emoji & ጥቅሎች',
    packsTitle: 'ኢሞጂ, ተለጣፊዎች & ጥቅሎች',
    packsDesc: 'የ emoji picker ሁሉ emoji ይሸከማል, ፍለጋ ጋር, የቆዳ ድምፆች እና recents, እና ሌሎች መተግበሪያዎች ከ emoji inline ያስቀምጣል. ከዚህም በላይ የባጅ መያዣዎች የራሳቸውን ኢሞጂ ፣ ተለጣፊ እና ጂአይኤፍ ጥቅሎች ያደርጉታል ፣ እና ማንም ሰው በመረጡት ላይ የተጋራ ጥቅል ማከል እና በውይይት ፣ በአስተያየቶች እና በምላሾች ውስጥ ሊጠቀምበት ይችላል ።',
    packsB1: 'ጥቅል ያድርጉ:',
    packsB1Desc: 'ኢሞጂ ፣ ተለጣፊ ወይም ጂአይኤፍ ጥቅል ለመገንባት ምስሎችን ይስቀሉ ወይም አገናኞችን ይለጥፉ ። ከፍተኛ ባጅ ደረጃዎች በእያንዳንዱ ውስጥ ተጨማሪ ጥቅሎችን እና ተጨማሪ ክፍልን ያገኛሉ ።',
    packsB2: 'አጋራ አጋራ:',
    packsB2Desc: 'እያንዳንዱ ጥቅል ለማጋራት አገናኝ ያለው በ dehub.io/packs ላይ የራሱ ገጽ አለው ፣ እና በጣም የተጨመሩ ጥቅሎች ለሁሉም ለማሰስ ተዘርዝረዋል ።',
    tocCinema: 'ሲኒማ',
    cinemaTitle: 'ሲኒማ',
