    themesDesc: 'DeHub አስራ አራት የመገለጫ አማራጮችን, ብርሃን-እና-ዳርክ toggle አይደለም: ስርዓት, ብርሃን, አነስተኛ, Cosmic, Hazy, Swarms, ላቫ መብራት, የክረምት, ጦርነት, ኦሳካ, ጫካ, ደሴት, ጠላፊ እና አስፈሪ. እያንዳንዳቸው ሙሉ ቆዳ ናቸው — የራሱ ፓሌት ፣ ክሮም ፣ አዶግራፊ እና ፣ ለብዙዎቹ ፣ በጂፒዩ ላይ የተተረጎመ የቀጥታ አኒሜሽን ዳራ ። ደሴት የወርቃማ ሰዓትዎን ከወርቅ ሰዓት እስከ ማታ የሚከተል ላጎን ነው ፣ ጠላፊ በሞኖስፔስ ውስጥ ከተቀመጠው መተግበሪያ ጋር ቀርፋፋ አረንጓዴ ዝናብ ነው ፣ እና አስፈሪ በተለበሰ የቪኤችኤስ ቴፕ ላይ ምስሎችን ያገኛል ። እያንዳንዳቸው ናሙና በሚያሳዩበት በቅንብሮች → መልክ ውስጥ አንዱን ይምረጡ; ከእነዚህም ውስጥ አራቱ የራስዎን የቃላት ቀለም እንዲያዘጋጁ ያስችልዎታል, እና ጁንግሌ የራሱ ቀን እና ምሽት መቀየሪያ አለው.',
    studioB4Desc: 'በ DeHub መለያዎች ውስጥ በአንድ ሥራ ይክፈሉ ፣ ከመሮጡ በፊት በተጠቀሰው ዋጋ ። ከባድ ተጠቃሚዎች ፈጣሪን ፣ አልትራ ፣ ቡድንን ወይም ስካሌ ፕላን ለወርሃዊ ምልክት አበል መውሰድ ይችላሉ — እቅዶቹ በ dehub.io/pricing ላይ ተዘርዝረዋል ።',
