    allowanceUnpaidTitle: 'ብትቀንስ',
    appsB2Desc: 'በ Google Play ላይ, ወይም በቀጥታ APK ማውረድ እንደ dehub.io/apk ለ Android 8 እና ከዚያ በላይ.',
    appsDesc: 'DeHub በየትኛውም ቦታ ይሠራል. በ dehub.io ላይ ያለው የድር መተግበሪያ በአሳሽ ውስጥ ሙሉ ምርት ሲሆን በዴስክቶፕም ሆነ በስልክ ላይ እንደ ተወላጅ መተግበሪያ ወደ መነሻ ማያ ገጽዎ ይጫናል. የ Android መተግበሪያ Google Play ላይ ነው, እና የቅርብ ጊዜ ግንባታ ሁልጊዜ መደብር መዝለል የሚመርጥ ማንኛውም ሰው ከ ቀጥተኛ APK እንደ ይገኛል. ምግቦች ፣ ደረጃዎች ፣ መለጠፍ ፣ መልእክት መላክ ፣ የኪስ ቦርሳ እና ማሳወቂያዎች ሁሉም በሁለቱም ላይ ተመሳሳይ ይሰራሉ ፣ እና መለያዎ ፣ ባጅዎ እና ሚዛኑ በመካከላቸው ይከተሉዎታል ።',
    arcadeTitle: 'አርከዲል',
    badgeDelegationB2: 'መክተቻዎች ከራስህ እንጨት የመጡ ናቸው:',
    badgeDelegationB3: 'ፓትርያርኩ በአደባባይ ፡ -',
    badgeDelegationB4Desc: 'ወደ ኋላ አንድ ማስገቢያ ውሰድ እና ደረጃው ወደ አንተ ይመለሳል. የራስዎ ማሰሪያ ፣ የክፍያ ደረጃ እና የተቆለፈ ባጅ እርስዎ በሚያበድሩት ማንኛውም ነገር ያልተነካ ነው ።',
    badgeDelegationB5Desc: 'የመሣሪያ ስርዓቱ የሚያሳየው የብድር ባጅ ነው ፣ እና ከደረጃው ጋር የሚሄድ ክብደትን ይሸከማል — ከሱ እይታ ወይም ምላሽ ብድር በነበረበት ደረጃ ይቆጥራል ። የማይሸከመው ነገር በገንዘብ ዋጋ ነው-እርስዎ የደመወዝ ደረጃ ፣ የእርስዎ ምልክት ግዢ ቅናሽ ፣ የዕለት ተዕለት መለጠፍ ድጎማዎ እና የራስዎ ልዑክ ቦታዎች አሁንም እራስዎን ከሚይዙት እንጨት ይነበባሉ ።',
    badgeDelegationB6: 'የረገጣችሁትን ማንኛውንም ሩጫ አበድሩ ፡ -',
    badgeDelegationTitle: 'ባጅዎን ያበድሩ',
    badgeUnlock1: 'ጠቃሚ ምክሮች, የክፍያ-እይታዎች, የደንበኝነት ምዝገባዎች እና ጉርሻዎች ላይ ዝቅተኛ ክፍያ, አንድ ደረጃ ወደታች 0.69%.',
    badgeUnlockTitle: 'ምን ባጅ ይከፍታል',
    boostPowerDesc: 'ባለፈው ሳምንት በቤት ውስጥ ምግብ አናት ላይ አንድ ልጥፍ ያስቀምጡ. ክራብ ላይ መክፈት. አሁን መኖር.',
    communitiesB1: 'ያስሱ & ይቀላቀሉ:',
    communitiesTitle: 'ማህበረሰቦች እና ክስተቶች',
    connectDesc: 'በ MCP በኩል ወደ ChatGPT ወይም ክላውድ አገናኝ DeHub እና በእርስዎ ምትክ ከመድረክ ጋር ለማሰስ ፣ ለመለጠፍ እና ለመግባባት የእርስዎን ተወዳጅ AI ይጠቀሙ ። በ dehub.io/connect ላይ ያዘጋጁት ።',
    featureBoardDesc: 'DeHub ከማህበረሰቡ ጋር ተገንብቷል ። በባህሪው ጥያቄ ቦርድ ላይ ሀሳቦችን ያስገቡ ፣ በሌሎች ሰዎች ጥያቄዎች ላይ ድምጽ ይስጡ ፣ እና ወደ መላኪያ ሲንቀሳቀሱ ይመለከታሉ — እርስዎ የጠየቁት ባህሪ በቀጥታ የሚሄድ ከሆነ መተግበሪያው በግል ማሳወቂያ ይነግርዎታል ።',
    feedsDesc2: 'ቅርጸቶች በምግቡ አናት ላይ እንደ ትሮች ይተላለፋሉ ። ነባሪው መነሻ ትር እርስዎ ከሚከተሉት ሰዎች እና ማህበረሰቦች ሁሉንም ነገር ያገናኛል; የወሰኑ ትሮች አንድ መካከለኛ ያገለሉ, ለምሳሌ, ረጅም-ቅርጽ ቪዲዮ ወይም ሙዚቃ ብቻ ማሰስ ይችላሉ. ደረጃ መስጠት በዚህ ገጽ ላይ በተመዘገበው የመድረክ መሪ ሰሌዳ ስልተ ቀመር ይነዳል ፣ ስለሆነም ጥራት እና ተሳትፎ ፣ የማስታወቂያ ወጪ አይደለም ፣ ተደራሽነትን ይወስናል ።',
    feedsShortsDesc: 'ለቲክቶክ-ቅጥ እይታ ቀጥ ያለ ፣ ተጣጣፊ አጭር ቪዲዮ ሪል ። አቅጣጫ የተቆለፈ የዥረት ምልክቶች ክሊፖች መካከል ይንቀሳቀሳሉ, ፍጥነት በአንድ ጊዜ ሁለት መዝለል ፈጽሞ ስለዚህ የተቆለፈ ነው, እና monetisation በእያንዳንዱ ክሊፖች ላይ ተፈጻሚ ነው.',
    feedsTabsDesc: 'በአንድ ጊዜ አንድ ቅርጸት ለማሰስ በቪዲዮዎች፣ ምስሎች፣ ሙዚቃ እና የቀጥታ ስርጭት ትሮች መካከል ይቀያይሩ፣ እያንዳንዳቸው ለዚያ ሚዲያ የተስተካከለ የራሱ አቀማመጥ አላቸው።',
    feedsTitle: 'የምግብ እና የይዘት ቅርጸቶች',
    moreB1Desc: 'መላው ምርት አንድ የውስጠ-መተግበሪያ የእግር ጉዞ, ማያ ገጽ በ ማያ ገጽ, ሰነዶችን ከማንበብ ይልቅ መታየት ለሚፈልግ ማንኛውም ሰው.',
    moreB4: 'መሪ ሰሌዳ & ከፍተኛ 100:',
    moreB6Desc: 'እርስዎን ወክለው የሚንቀሳቀሱ ወኪሎችን ያሰማሩ ፣ እና በጥያቄ ወደ ረዳት በቀጥታ ለማግኘት ፈጣን ወለል ።',
