    moreDesc: 'መተግበሪያው ውጭ ዙሪያ ትናንሽ ወለሎች ጥቂት. ማንም ሰው ረጅም ማብራሪያ አያስፈልገውም, ነገር ግን ማንም ከእነርሱ ላይ ነጥብ ከሆነ ማጣት ቀላል ነው.',
    msg6: 'ብልጥ ምላሾች: ሁለት የተጠቆሙ መልሶች ከፀሐፊው በታች ለሁለቱም የውይይቱ ጎኖች በቧንቧ ውስጥ መላክ ወይም ማርትዕ ይችላሉ',
    notificationsB1: 'ወደ እርስዎ የሚደርሰውን ይምረጡ:',
    notificationsDesc: 'በአንድ የማሳወቂያ ማዕከል ውስጥ ለእርስዎ የሚከሰት ነገር ሁሉ ፣ በትሮች ተከፍሏል ስለሆነም መልሶች ክፍያዎችን አይቀበሩም ። አስተያየቶች እና ምላሾች ፣ በልጥፎችዎ ፣ በአዳዲስ ተከታዮችዎ ፣ ምክሮች እና ግዢዎችዎ ላይ ምላሾች ፣ የመድረክ አስታዋሾች እና እርስዎ ያዙት ደረጃ በቀጥታ የሚሄድበት ፣ የማህበረሰብ እንቅስቃሴ እና በጥያቄ ቦርድ ላይ የጠየቁት ባህሪ በእውነቱ መርከቦች — ሁሉም በአንድ ቦታ ላይ ፣ ማሳወቂያው ስለማንኛውም ነገር ድንክዬ ጋር ፣ በጨረፍታ መለየት ይችላሉ ።',
