    stagesB4: 'መዝገቦች:',
    stagesDesc: 'ደረጃዎች በቀጥታ ወደ DeHub የተገነቡ ከትዊተር ቦታዎች ጋር ሊነፃፀሩ የሚችሉ የቀጥታ ኦዲዮ ክፍሎች ናቸው ። አስተናጋጅ አንድ ክፍል ይከፍታል ፣ ተናጋሪዎችን በደረጃ ያመጣል ፣ እና ማንኛውም ቁጥር አድማጮች ወዲያውኑ ከደረጃ ገጹ ወይም ከተጋራ የግብዣ አገናኝ መጣል ይችላሉ ። ደረጃዎች ለመለኪያ በእውነተኛ ውይይት የተነደፉ ናቸው: አስተናጋጆች ማን መናገር እንደሚችል ይቆጣጠራሉ, አድማጮች የቀጥታ ምላሾችን ይልኩ, እና መላው ክፍል እንደገና ለመመዝገብ ሊመዘገብ ይችላል.',
    stagesTitle: 'ደረጃዎች: የቀጥታ ኦዲዮ ክፍሎች',
    storesB2: 'ለቶኬቶች ይሽጡ:',
    storesB2Desc: 'ምርቶች በተገነባው የኪስ ቦርሳ በኩል በ DeHub ምልክቶች ውስጥ ዋጋ ያላቸው እና የተቀመጡ ናቸው ፣ ምንም ውጫዊ ቼክ የለም ።',
    studioB1Desc: 'ምስሎች ፣ ቪዲዮ ፣ ሙዚቃ ፣ ድምጽ ማጉያ እና 3D ሞዴሎች ፣ ስቱዲዮው ሥራ ከመሮጡ በፊት በአገልጋዩ ያጋልጣል ፣ ዋጋ ያስከፍላል እና ይጠቅሳል ።',
    studioB2Desc: 'በአሳሹ ውስጥ ባለብዙ ትራክ የጊዜ መስመር አርታዒ ፣ ከኤክስፖርት ጋር ። ለመጫን ምንም ነገር እና ለሶስተኛ ወገን ለመስቀል ምንም ነገር የለም ።',
    studioB3Desc: 'አከራዮች በሚያስሱበት ጊዜ በተጋራ ወረፋ ውስጥ ይቀጥላሉ ፣ እና ነፃ የአክሲዮን ንብረት ቤተ-መጽሐፍት ክፍተቶችን ይሸፍናል ።',
    studioB4: 'ክሬዲት ወይም ዕቅድ:',
    studioDesc2: 'ከጎኑ በአሳሹ ውስጥ የሚሰራ ሙሉ የቪዲዮ አርታዒ ነው — በመቁረጥ ፣ በመጣል እና በመላክ እውነተኛ ባለብዙ ትራክ የጊዜ መስመር ፣ ትሪም ተንሸራታች አይደለም ። በስቱዲዮው ፣ በሰቀሉት ሚዲያዎች እና በንብረት ቤተ-መጽሐፍት ውስጥ ያመነጩት ምስሎች ሁሉም በተመሳሳይ የጊዜ መስመር ላይ ይወድቃሉ ፣ እና የተጠናቀቀው ቁረጥ በቀጥታ ወደ ልጥፍ ፣ በአጭር ወይም በሱቅ ዝርዝር ውስጥ ይሄዳል ።',
    superPowersDescV2: 'ልዕለ ኃያላን ሊያሳልፏቸው በሚችሏቸው መድረሻ ላይ የተንሸራታች ባጅ ይለውጣሉ ። በየሳምንቱ ባጅዎ ድጎማዎችን ያበረታታል ፣ እና አንድን ማሳለፍ በቤት ምግብ አናት ላይ ባለው ማስገቢያ ውስጥ አንድ ልጥፍ ያስቀምጣል ። ቡድኑ ለሁሉም ክፍት ነው እና እስከ ስምንት መለያዎች የኪስ ኃይልን ያጣምራል ፣ ለእያንዳንዱ አባል አጠቃላይ ክፍተቶቻቸውን ባጅ ይሰጣል ። ማስገቢያ ይሽከረከራል: በርካታ ማበረታቻዎች በሚሰሩበት ጊዜ ተመልካቾች አንድ በባጅ ደረጃ ይመዝናሉ, ስለዚህ ከፍ ያለ ደረጃ የበለጠ በተደጋጋሚ ይታያል እና ሁሉም ሰው አሁንም የተሰጠውን መስኮት ያገኛል.',
