    trendJackerDesc2: 'ወደ አዝማሚያ ዝርዝር አናት ላይ የእርስዎን ምድቦች አንዱን ያስቀምጡ. ግዙፍ Tortoise ላይ መክፈት. አሁን መኖር.',
    tvRadioB2Desc: 'ትራኮች, የሙዚቃ ቪዲዮዎች, ፖድካስቶች እና የቀጥታ አፈጻጸም ትሮች ጋር የወሰኑ የሙዚቃ ወለል, እያንዳንዱ የራሱ ተጫዋች ጋር.',
    tvRadioB3: 'ሬዲዮ:',
    walletHubB1: 'የኪስ ቦርሳ:',
    walletHubB2: 'የትእዛዝ ማዕከል:',
    walletHubDesc2: 'ለፈጣሪዎች እና ለኃይል ተጠቃሚዎች የኪስ ቦርሳው ወደ ሙሉ የፋይናንስ ወለል ይስፋፋል ። የትእዛዝ ማዕከል በጊዜ ሂደት ገቢን ይመለከታል ፣ እያንዳንዱን ግብይት ይሰብራል ፣ እና የመስቀል ቻይን ተቀማጭ ገንዘብን ያስተናግዳል ፣ የወሰኑ ገጾች ከ DeHub ሳይወጡ የ DeHub ምልክቶችን እንዲገዙ ፣ እንዲወክሉ እና እንዲወገዱ ያስችልዎታል ።',
    walletHubLink: 'የቶከን ዶክስን ይመልከቱ ኢኮኖሚክስ ፣ ቁፋሮ እና ድልድይ በጥልቀት ።',
    workB1Desc: 'ማንኛውም ሰው በ DeHub ምልክቶች ወይም USDC ውስጥ ግልጽ አጭር እና ሽልማት ያለው ስጦታ መለጠፍ ይችላል ፣ ሊሰጥ የሚገባው የሥራ ቁራጭ ወይም እንደ ማጋራት ፣ ክሊፕ ማድረግ ወይም ይዘትን ማስተዋወቅ ያሉ የተሳትፎ ተግባር ነው ።',
    workB3Desc: 'ቦንቶች በማኅበራዊ ሚዲያ ፣ በመለያ እና በኮንትራት የተደራጁ ናቸው ፣ ስለሆነም የተሳትፎ ተግባራት እና ረዘም ያሉ የሥራ ቁርጥራጮች እያንዳንዳቸው የራሳቸው መንገድ አላቸው ።',
    workB4: 'Escrow ጥበቃ:',
    workB5Desc: 'ፈጣሪዎች ማህበረሰቦቻቸውን ለማሳደግ ቦንሶችን ይለጥፋሉ ፣ እና የዴሁብ ማህበረሰብ እራሳቸውን ለማሰራጨት እና ሥነ ምህዳሩን ለማስፋት ቦንቦችን ይለጥፋል ፣ ማስተዋወቂያውን ወደ ተሸላሚ ፣ ትራኪንግ እንቅስቃሴ ይለውጣል ።',
    workB6: 'ክርክሮች:',
    workDesc: 'Bounty Hunting የ DeHub አብሮገነብ ተግባር እና የሽልማት ስርዓት ነው ፣ የሶስተኛ ወገን ነፃ ገበያ አይደለም ። በስነ-ምህዳር ውስጥ ያለ ማንኛውም ሰው የችሮታ መለጠፍ ይችላል ፣ እና ማንኛውም ሰው ሥራው እስኪሰጥ ድረስ በደህና በተያዘው ሽልማት የአደን እና የይገባኛል ጥያቄ ማቅረብ ይችላል ። ወደ መድረኩ ተወላጅ ክፍል ሥራ እና ተሳትፎ ይለውጣል-ቡናዎችን የሚለጥፉ ሰዎች ፣ እነሱን የሚያጠናቅቁ አዳኞች እና ሁሉንም የሚያስተካክሉ ምልክቶች በዴሁብ ውስጥ ይኖራሉ ። ባንኮች በ DeHub ምልክቶች ወይም በ USDC ውስጥ ይከፈላሉ ።',
    workDesc2: 'ምክንያቱም የአገሬው ተወላጅ ስለሆነ ፣ ቦንቲ አደን ለመላው ሥነ ምህዳር የእድገት ሞተር በእጥፍ ይጨምራል ። ፈጣሪዎች ለአክሲዮኖች ፣ ክሊፖች ፣ ምላሾች ወይም ሥራቸውን የሚያሰራጩ ይዘቶችን በመለጠፍ ተሳትፎን ለማሽከርከር እና ማህበረሰቦቻቸውን ለመገንባት ይጠቀማሉ ። ፕሮጀክቶች እና ሰፊው የዴሁብ ማህበረሰብ አዲስ ሰዎችን ለሚያመጡ ተግባራት አደን ወሮታ በመስጠት እራሳቸውን ለማራመድ እና ሥነ ምህዳሩን ለማሳደግ ይጠቀማሉ ። ስምምነትን የሚያስተካክል ተመሳሳይ ስርዓት እንዲሁ የማህበረሰብ ተሳትፎ ሥራን ያዘጋጃል ።',
