    preventFraudDesc1: 'ቦቶች ያነሰ ትርፋማ ይሆናሉ እንቅስቃሴው በሰንሰለት ላይ ሊከታተል በሚችልበት ጊዜ፣ መጥፎ ተዋንያንን በቀላሉ በማገናኘት እና በመጨረሻም የተጠቃሚውን መሰረት በሙሉ በማስተባበር። አስተዋዋቂዎች ከፍተኛ ደረጃዎችን ያነጣጠራሉ፣ በታችኛው ንብርብር ላይ አነስተኛ ሊወጣ የሚችል እሴት ይተዋል፣ የትኛውም የቀረ አጭበርባሪ ይቀራል። ከዚህም በላይ፣ የእኛ የተማከለ አስተዳደር ይበልጥ ውጤታማ የሆነ ህገ-ወጥ እንቅስቃሴን ማወቅ እና መከላከልን ይፈቅዳል።',
