    howItWorksDesc2: 'ይህ መንገድ ለአንድ አካል ብቻ ሳይሆን ለጠቅላላው ሥነ-ምህዳር ይጠቅማል። የይዘት ፈጣሪዎች፣ ተጠቃሚዎች፣ ባለቤቶች እና በመድረክ ላይ የሚያስተዋውቁ ኩባንያዎች ሁሉም የበለጠ ሽልማቶችን ያገኛሉ።',
