    step1Title: 'መለያዎን ይፍጠሩ',
    step1Desc: 'ክፈት dehub.io እና መታ ይግቡ. ጉግል, አፕል, ቴሌግራም, ኢሜይል, ኤስኤምኤስ, ማለፊያ ወይም የኪስ ቦርሳ ይምረጡ. ከጀርባው ውስጥ ያልተፈጠረ የኪስ ቦርሳ ለእርስዎ ተፈጥሯል — ቁልፎቹን ይይዛሉ — እና ጋዝ ስፖንሰር ነው ፣ ስለሆነም ከመጀመርዎ በፊት የገንዘብ ድጋፍ የሚደረግበት ምንም ነገር የለም ።',
    step2Title: 'መገለጫዎን ያዋቅሩ',
    step2Desc: 'በቅንብሮች → መገለጫ ውስጥ የማሳያ ስም ፣ የተጠቃሚ ስም ፣ አቫታር ፣ ምስልን እና ባዮ ያክሉ ፣ እና መገለጫዎ አጠቃላይ መድረሻዎን ለማሳየት ሌሎች ማህበራዊ አውታረ መረቦችዎን ያገናኙ ። እዚያ በሚሆኑበት ጊዜ በቅንብሮች → መልክ ውስጥ ጭብጥ ይምረጡ ፣ እና በዙሪያው ለመታየት ከፈለጉ አማራጭን የሚመሩ የእግር ጉዞዎችን ይውሰዱ ።',
    step3Title: 'የመጀመሪያ ልጥፍዎን ያድርጉ',
    step3Desc: 'መታ ፍጠር. አንድ ልጥፍ ይጻፉ, ምስሎችን, ቪዲዮዎችን ወይም ኦዲዮዎችን ያክሉ, ለረጅም ቅርጽ መጻፍ ወደ ጽሑፍ ይቀይሩ, ወይም በቀጥታ ይሂዱ. መለጠፍ እስከ ዕለታዊ ድጎማ ድረስ ነፃ ነው — አስር የጽሑፍ ልጥፎች እና ያለ ባጅ በየቀኑ የሚዲያ ጊጋባይት ። በቻይን ላይ ልኡክ ጽሁፍ መቀባት አማራጭ ነው እና በኋላ ላይ ሊከናወን ይችላል ።',
    step4Title: 'ከአድማጮችዎ ያግኙ',
    step4Desc: 'እያንዳንዱ ልኡክ ጽሁፍ በ DeHub ቶከኖች ውስጥ ሊጣበቅ ይችላል ። ከዚያ የደንበኝነት ምዝገባዎችን መሸጥ ፣ የክፍያ-እይታ ልጥፎችን ማተም ፣ ለቀጥታ መልዕክቶች አነስተኛ ጠቃሚ ምክሮችን ማዘጋጀት ፣ ሱቅ መክፈት ፣ ሽልማቶችን መለጠፍ እና ከሚያመጡዋቸው ሰዎች ገቢ ለማግኘት ተጓዳኝ አገናኝዎን ማጋራት ይችላሉ ።',
    step5Title: 'ምልክት ለባጅ ይያዙ',
    step5Desc: 'የ DeHub ምልክቶችን መያዝ ወይም ማጭበርበር ከ Crab እስከ Megalodon ባጅ ያገኛል ። ባጅ ክፍያዎን ይቀንሳል ፣ የመለጠፍ ድጎማዎን ከፍ ያደርገዋል ፣ SuperPowers ን ይከፍታል እና በአስተያየቶችዎ ፣ በምላሾችዎ እና በድምጾችዎ ላይ ክብደት ይጨምራል ።',
    step6Title: 'የኪስ ቦርሳዎን ይጠቀሙ',
    step6Desc: 'የኪስ ቦርሳዎ በበርካታ ሰንሰለቶች ላይ የ DeHub ምልክቶችን እና ሌሎች ምስጢሮችን ይይዛል ። ምልክቶችን በካርድ ወይም በ crypto ከ $ 0.50 ይግዙ ፣ በነፃ ለማንም ይላኩ ፣ በ DeHub ልውውጥ ላይ ይነጋገሩ ፣ እና የባጅ መሰላልን ለመውጣት እንጨት ።',
    congratulations: '🎉 ተዘጋጅተሃል',
    congratulationsDesc: 'መለያ ፣ መገለጫ እና የመጀመሪያ ልጥፍ አለዎት ። የ dApp መመሪያ መተግበሪያው ማድረግ ይችላል ሌላ ነገር ሁሉ ይሸፍናል.',
